mapper.select:
/* isry.itgcm.casemng.caseunity.CaseExcnMapper.selectCaseExcnHstrList(사례제공이력목록조회) */ SELECT T1.RESRCE_NO AS RESRCE_NO -- 자원번호 , T1.RESRCE_NM AS RESRCE_NM -- 자원명 , NVL((SELECT INST_NM FROM SAA000 WHERE INST_NO = T1.RSFR_INST_NO), (SELECT INST_NM FROM SDA600 WHERE INST_NO = T1.RSFR_INST_NO)) AS RSFR_INST_NM -- 자원제공주체명 , CASE WHEN T1.SRVC_EXCN_BIZ_CHC_PSBLTY_YN = 'Y' THEN T1.SEB500_SRVC_EXCN_BIZ_NO ELSE '' END AS SRVC_EXCN_BIZ_NO -- 서비스실행사업번호 , (SELECT X.SRVC_EXCN_BIZ_NM FROM SDA420 X WHERE X.SRVC_EXCN_BIZ_NO = CASE WHEN T1.SRVC_EXCN_BIZ_CHC_PSBLTY_YN = 'Y' THEN T1.SEB500_SRVC_EXCN_BIZ_NO ELSE T1.SDA100_SRVC_EXCN_BIZ_NO END) AS SRVC_EXCN_BIZ_NM -- 서비스실행사업명 , T1.SRVC_TYPE_SE_CD AS SRVC_TYPE_SE_CD -- 서비스유형구분코드 , T1.SRVC_RESRCE_LCLAS_SE_CD AS SRVC_RESRCE_LCLAS_SE_CD -- 서비스자원대분류구분코드 , T1.SRVC_PVSN_PLAN_NO AS SRVC_PVSN_PLAN_NO -- 서비스제공계획번호 , T1.SRVC_PVSN_MTHD_SE_CD AS SRVC_PVSN_MTHD_SE_CD -- 서비스제공방법구분코드 , T1.SRVC_PVSN_TTL_NM AS SRVC_PVSN_TTL_NM -- 서비스제공제목명 , T1.SRVC_PVSN_CN AS SRVC_PVSN_CN -- 서비스제공내용 , T1.SRVC_PVSN_BGNG_YMD AS SRVC_PVSN_BGNG_YMD -- 서비스제공시작일자 , T1.SRVC_PVSN_END_YMD AS SRVC_PVSN_END_YMD -- 서비스제공종료일자 , T1.SRVC_PVSN_BGNG_HR AS SRVC_PVSN_BGNG_HR -- 서비스제공시작시간 , T1.SRVC_PVSN_END_HR AS SRVC_PVSN_END_HR -- 서비스제공종료시간 , T1.PIC_NO AS PIC_NO -- 담당자번호 , (SELECT C##RG.DEC_B64(FLNM_ENCPT) FROM SCA100 WHERE ENFSN_NO = T1.PIC_NO) AS PIC_NM -- 담당자명 , T1.TKCG_INST_NO AS TKCG_INST_NO -- 담당기관번호 , (SELECT INST_NM FROM SAA000 WHERE INST_NO = T1.TKCG_INST_NO) AS TKCG_INST_NM -- 담당기관명 , T1.SRVC_PVSN_YN AS SRVC_PVSN_YN -- 서비스제공여부 , T1.SRVC_PVSN_RESULT_CN AS SRVC_PVSN_RESULT_CN -- 서비스제공결과내용 , T1.SRVC_PVSN_WHDA_YN AS SRVC_PVSN_WHDA_YN -- 서비스제공전일여부 , T1.SRVC_GR_PVSN_YN AS SRVC_GR_PVSN_YN -- 서비스집단제공여부 , T1.ATFINO AS ATFINO -- 첨부파일번호 FROM ( SELECT T1.RESRCE_NO AS RESRCE_NO -- 자원번호 , T3.PVSN_RESRCE_NM AS RESRCE_NM -- 자원명 , T3.RSFR_INST_NO AS RSFR_INST_NO , T3.SRVC_EXCN_BIZ_NO AS SDA100_SRVC_EXCN_BIZ_NO , T2.SRVC_EXCN_BIZ_NO AS SEB500_SRVC_EXCN_BIZ_NO , T3.SRVC_TYPE_SE_CD AS SRVC_TYPE_SE_CD -- 서비스유형구분코드 , T3.SRVC_RESRCE_LCLAS_SE_CD AS SRVC_RESRCE_LCLAS_SE_CD -- 서비스자원대분류구분코드 , T2.SRVC_PVSN_PLAN_NO AS SRVC_PVSN_PLAN_NO -- 서비스제공계획번호 , T2.SRVC_PVSN_MTHD_SE_CD AS SRVC_PVSN_MTHD_SE_CD -- 서비스제공방법구분코드 , T2.SRVC_PVSN_TTL_NM AS SRVC_PVSN_TTL_NM -- 서비스제공제목명 , T2.SRVC_PVSN_CN AS SRVC_PVSN_CN -- 서비스제공내용 , T2.SRVC_PVSN_BGNG_YMD AS SRVC_PVSN_BGNG_YMD -- 서비스제공시작일자 , T2.SRVC_PVSN_END_YMD AS SRVC_PVSN_END_YMD -- 서비스제공종료일자 , T2.SRVC_PVSN_BGNG_HR AS SRVC_PVSN_BGNG_HR -- 서비스제공시작시간 , T2.SRVC_PVSN_END_HR AS SRVC_PVSN_END_HR -- 서비스제공종료시간 , T2.PIC_NO AS PIC_NO -- 담당자번호 , T2.TKCG_INST_NO AS TKCG_INST_NO -- 담당기관번호 , T1.SRVC_PVSN_YN AS SRVC_PVSN_YN -- 서비스제공여부 , T1.SRVC_PVSN_RESULT_CN AS SRVC_PVSN_RESULT_CN -- 서비스제공결과내용 , T2.SRVC_PVSN_WHDA_YN AS SRVC_PVSN_WHDA_YN -- 서비스제공전일여부 , NVL(( SELECT Z.ADDTNG_MNG_VALUE3 FROM SAC100 Z WHERE Z.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND Z.CMMNS_CD_VALUE = ( SELECT Y.UNT_TASKWK_SE_CD FROM SEB100 Y WHERE Y.CASE_MNG_NO = T1.CASE_MNG_NO AND Y.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO ) ), 'N') AS SRVC_EXCN_BIZ_CHC_PSBLTY_YN -- 서비스실행사업선택가능여부 , T2.SRVC_GR_PVSN_YN AS SRVC_GR_PVSN_YN -- 서비스집단제공여부 , T2.ATFINO AS ATFINO -- 첨부파일번호 FROM SEB510 T1 /* 서비스제공대상자 */ , SEB500 T2 /* 서비스제공 */ , SDA100 T3 /* 자원기본 */ WHERE T1.SRVC_PVSN_NO = T2.SRVC_PVSN_NO AND T1.RESRCE_NO = T2.RESRCE_NO AND T1.RESRCE_NO = T3.RESRCE_NO(+) AND T1.CASE_MNG_NO = #{CASE_MNG_NO} AND T1.DEL_YN != 'Y' AND T2.DEL_YN != 'Y' AND (T2.SRVC_PVSN_BGNG_YMD BETWEEN #{SRVC_PVSN_BGNG_YMD} AND #{SRVC_PVSN_END_YMD} OR T2.SRVC_PVSN_END_YMD BETWEEN #{SRVC_PVSN_BGNG_YMD} AND #{SRVC_PVSN_END_YMD} OR #{SRVC_PVSN_BGNG_YMD} BETWEEN T2.SRVC_PVSN_BGNG_YMD AND T2.SRVC_PVSN_END_YMD OR #{SRVC_PVSN_END_YMD} BETWEEN T2.SRVC_PVSN_BGNG_YMD AND T2.SRVC_PVSN_END_YMD)
AND T3.PVSN_RESRCE_NM LIKE '%'||#{RESRCE_NM}||'%'
ORDER BY T2.SRVC_PVSN_BGNG_YMD DESC ) T1

mapper.insert:
INSERT /* isry.itgcm.casemng.caseunity.CaseExcnMapper.insertSEB500Data(서비스제공등록) */
  INTO SEB500 T1 /* 서비스제공 */
     (  T1.SRVC_PVSN_NO             -- 서비스제공번호(SR)
      , T1.RESRCE_NO                -- 자원번호
      , T1.SRVC_PVSN_PLAN_NO        -- 서비스제공계획번호
      , T1.SRVC_PVSN_RQST_NO        -- 서비스제공의뢰번호
      , T1.SRVC_PVSN_MTHD_SE_CD     -- 서비스제공방법구분코드
      , T1.SRVC_PVSN_TTL_NM         -- 서비스제공제목명
      , T1.SRVC_PVSN_CN             -- 서비스제공내용
      , T1.SRVC_PVSN_BGNG_YMD       -- 서비스제공시작일자
      , T1.SRVC_PVSN_END_YMD        -- 서비스제공종료일자
      , T1.SRVC_PVSN_BGNG_HR        -- 서비스제공시작시간
      , T1.SRVC_PVSN_END_HR         -- 서비스제공종료시간
      , T1.SRVC_PVSN_WHDA_YN        -- 서비스제공전일여부
      , T1.SRVC_EXCN_BIZ_NO         -- 서비스실행사업번호
      , T1.PIC_NO                   -- 담당자번호
      , T1.TKCG_INST_NO             -- 담당기관번호
      , T1.SRVC_GR_PVSN_YN          -- 서비스집단제공여부
      , T1.ATFINO                   -- 첨부파일번호
      , T1.DEL_YN                   -- 삭제여부
      , T1.FRST_RGTR_ID             -- 최초등록자아이디
      , T1.FRST_REG_DT              -- 최초등록일시
      , T1.LAST_MDFR_ID             -- 최종수정자아이디
      , T1.LAST_MDFCN_DT            -- 최종수정일시
     )
VALUES
     (  #{SRVC_PVSN_NO}
      , #{RESRCE_NO}
      , #{SRVC_PVSN_PLAN_NO}
      , #{SRVC_PVSN_RQST_NO}
      , #{SRVC_PVSN_MTHD_SE_CD}
      , #{SRVC_PVSN_TTL_NM}
      , #{SRVC_PVSN_CN}
      , #{SRVC_PVSN_BGNG_YMD}
      , #{SRVC_PVSN_END_YMD}
      , #{SRVC_PVSN_BGNG_HR}
      , #{SRVC_PVSN_END_HR}
      ,  CASE WHEN #{SRVC_PVSN_BGNG_HR} IS NULL AND #{SRVC_PVSN_END_HR} IS NULL THEN 'Y'
             ELSE 'N'
         END
      , #{SRVC_EXCN_BIZ_NO}
      , #{PIC_NO}
      , #{TKCG_INST_NO}
      , NVL(#{SRVC_GR_PVSN_YN}, 'N')
      , #{ATFINO}
      , NVL(#{DEL_YN}, 'N')
      , #{USER_ID}
      , SYSDATE
      , #{USER_ID}
      , SYSDATE
     )

mapper.update:
UPDATE SEB540 T1
   SET T1.DEL_YN = 'Y'
 WHERE T1.SRVC_PVSN_NO             = #{SRVC_PVSN_NO}  
   AND T1.CASE_MNG_NO              = #{CASE_MNG_NO}    
   AND T1.CASE_MNG_ODRNO           = #{CASE_MNG_ODRNO}     
   AND T1.RESRCE_NO                = #{RESRCE_NO}  
   AND T1.EXCN_SRVC_BIZ_CL_NO      = #{EXCN_SRVC_BIZ_CL_NO}
   AND T1.EXCN_SRVC_DETAIA_BIZ_NO  = #{EXCN_SRVC_DETAIA_BIZ_NO}
